local ui=require("ui");local M={};local function clean(s) s=s:gsub("<script.-</script>"," "):gsub("<style.-</style>"," "):gsub("<[^>]+>"," "):gsub("&nbsp;"," "):gsub("&amp;","&");return s end
function M.run(m) ui.clear(m);ui.header(m,"WEB READER");m.setCursorPos(2,3);m.write("URL (computer keyboard):");term.write("> ");local url=read();if not url:match("^https?://") then sleep(1);return end;local ok,h=pcall(http.get,url,nil,true);if not ok or not h then m.setCursorPos(2,5);m.write("Request failed.");sleep(1.5);return end;local body=h.readAll();h.close();local text=clean(body);ui.clear(m);ui.header(m,"WEB READER");local w,hh=m.getSize();local y=3;for line in text:gmatch("[^\n]+") do while #line>0 and y<hh do local p=line:sub(1,w-2);m.setCursorPos(2,y);m.write(p);y=y+1;line=line:sub(#p+1) end end;ui.back(m);while true do local _,x,yy=os.pullEvent("monitor_touch");if yy==hh and x<=10 then return end end end
return M
